              ['"I **have finished**."', "\u2026she **had finished**."],
              ['"I **finished**."', "\u2026she **had finished**."],
              ['"I **will call**."', "\u2026she **would call**."],
              ['"I **can** help."', "\u2026she **could** help."],
              ['"I **must** go."', "\u2026she **had to** go."]
